// Phase 4: private published snapshots, explicit review, and atomic server merge.
let collaborationContext=null,collaborationChecking=false;
async function refreshCollaborationStatus(){
 if(collaborationChecking||!api||!user||view!=='dashboard'||root.hidden||document.hidden)return;
 const owner=user.id,panel=root.querySelector('#pc-collaboration-status');if(!panel)return;
 collaborationChecking=true;
 try{const rows=unwrap(await api.rpc('my_collaboration_updates'))||[];if(user?.id!==owner||view!=='dashboard'||!panel.isConnected)return;
 const pending=rows.filter(x=>x.published_revision>x.applied_revision);panel.replaceChildren(el('h2','Planner updates'),el('p',pending.length?`${pending.length} trip${pending.length===1?' has':'s have'} planner changes waiting for review.`:rows.length?'Your connected trips are up to date.':'No connected planner trips.','pc-sub'));
 for(const x of rows){const target=[...root.querySelectorAll('[data-cloud-trip]')].find(n=>n.dataset.cloudTrip===x.trip_id);const title=target?.querySelector('h2')?.textContent||'Connected trip';row(panel,el('span',title+' · '+(x.published_revision>x.applied_revision?'Update available':'Up to date')),button('Review planner details',()=>openCollaboration(x.trip_id),x.published_revision>x.applied_revision));}
 }catch(e){if(user?.id===owner&&panel.isConnected)panel.replaceChildren(el('h2','Planner updates'),el('p','Unable to check updates. Check your connection or apply the Phase 4 database migration.','pc-sub'),button('Retry',refreshCollaborationStatus));}finally{collaborationChecking=false;}
}
async function openCollaboration(id){const owner=user?.id;if(!owner)throw Error('Sign in first.');const trip=unwrap(await api.from('account_trips').select('*').eq('id',id).maybeSingle());const update=unwrap(await api.rpc('review_client_update',{p_trip:id}));if(user?.id!==owner)return;if(!trip||!update)throw Error('Planner connection unavailable.');collaborationContext={owner,trip,update};openPortal('collaboration');}
const collaborationFields={title:'Trip name',arrival:'Arrival',departure:'Departure',resort:'Resort',destination:'Destination',party_size:'Party size',notes:'Trip notes'};
function sameValue(a,b){if(a===b)return true;if(a==null||b==null||typeof a!==typeof b||typeof a!=='object')return false;if(Array.isArray(a)!==Array.isArray(b))return false;const keys=Object.keys(a);return keys.length===Object.keys(b).length&&keys.every(k=>Object.hasOwn(b,k)&&sameValue(a[k],b[k]));}
function plannerDiff(base,latest,current){const changes=[];for(const [k,label] of Object.entries(collaborationFields)){if(!sameValue(base[k],latest[k]))changes.push({label,before:base[k],after:latest[k],current:current[k],conflict:!sameValue(current[k],base[k])&&!sameValue(current[k],latest[k])});}const map=v=>new Map(reservationRows(v).map(r=>[r.id,r]));const b=map(base),p=map(latest),t=map(current);for(const id of new Set([...b.keys(),...p.keys()])){const before=b.get(id),after=p.get(id),own=t.get(id);if(!sameValue(before,after))changes.push({label:(after||before).title,before,after,current:own,conflict:!sameValue(own,before)&&!sameValue(own,after)});}return changes;}
function describePlannerValue(v){if(v===undefined||v===null)return 'Not present';if(typeof v!=='object')return String(v)||'Not set';return [v.title,v.kind,v.status,v.date,v.time,v.end_date?'End '+v.end_date:'',v.provider,v.location,v.confirmation?'Confirmation: '+v.confirmation:'',`Cost ${usd(v.cost_cents||0)} · Paid ${usd(v.paid_cents||0)}`,v.due_date?'Due '+v.due_date:'',v.details].filter(Boolean).join(' · ');}
function collaborationScreen(){const ctx=collaborationContext;if(!ctx||ctx.owner!==user?.id){openPortal('dashboard');return;}const {trip,update}=ctx,changes=plannerDiff(update.baseline,update.snapshot,trip);const pending=update.published_revision>update.applied_revision;const header=card('Planner update review',trip.title+' · '+(pending?'New changes waiting':'No pending changes'));row(header,button('Back to my trips',()=>openPortal('dashboard')),button('Reload latest',()=>openCollaboration(trip.id)));header.append(el('p','Applying an update merges planner changes into your cloud trip. Your separate reservations and unchanged personal plans are preserved. Conflicting changes must be reconciled first. Local countdown details can be restored separately.','pc-sub'));
 const list=card('Published changes',changes.length?'Compare the previous planner version, the new version and your current details.':'No changed client-facing fields.');for(const c of changes){const item=el('article','','pc-res-item');item.append(el('h3',c.label),el('p','Previous planner: '+describePlannerValue(c.before),'pc-res-notes'),el('p','New planner: '+describePlannerValue(c.after),'pc-res-notes'));if(c.conflict)item.append(el('p','Conflict — your version: '+describePlannerValue(c.current),'pc-res-notes'));list.append(item);}
 if(pending){const apply=card('Apply to my trip',changes.some(x=>x.conflict)?'At least one value changed on both sides. Edit your cloud trip or ask your planner to resolve the conflict, then reload this review. No changes have been applied.':'Only the reviewed published version will be applied.');const b=button('Apply planner update',async()=>{if(!confirm('Apply the reviewed changes to your cloud trip? Your personal countdown stays unchanged until you restore cloud details.'))return;unwrap(await api.rpc('apply_client_update',{p_trip:trip.id,p_revision:versionOf(trip),p_published:update.published_revision}));if(user?.id!==ctx.owner)return;message('Planner update applied to your cloud trip. Restore cloud details to update the countdown.');openPortal('dashboard');},true);b.disabled=changes.some(x=>x.conflict);apply.append(b);}
 const snapshot=card('Latest published itinerary','Reference copy from your planner; distinct from your editable cloud trip.');for(const [k,label] of Object.entries(collaborationFields))snapshot.append(el('p',label+': '+describePlannerValue(update.snapshot[k]),'pc-res-notes'));for(const r of reservationRows(update.snapshot))snapshot.append(el('p',describePlannerValue(r),'pc-res-notes'));const disconnect=card('Planner connection','Disconnecting stops future sharing. Your existing trip and reservations remain in your account.');disconnect.append(button('Disconnect planner',async()=>{if(!confirm('Disconnect this trip from your planner? Your saved trip remains.'))return;unwrap(await api.rpc('disconnect_client_update',{p_trip:trip.id}));if(user?.id===ctx.owner){message('Planner disconnected.');openPortal('dashboard')}}));}
// Phase 6: opt-in, independently versioned private snapshots. Never upload raw storage.
const SYNC_KEY='parkCountdown.account.snapshots.v1';
const syncFields={plans:['id','date','time','name','kind','park','note','done'],checks:['name','done'],expenses:['id','name','amount'],rides:['id','park','name','date','time','wait'],milestones:['id','name','date','done'],wish:['id','park','name']};
const syncDefaults=['Pack park tickets / passes','Pack chargers','Pack sunscreen','Pack comfortable shoes','Confirm dining plans','Confirm transportation'];
const syncObject=x=>x&&typeof x==='object'&&!Array.isArray(x)?x:{};
function syncText(x){if(typeof x!=='string')return '';if(x.length>8000||/^\s*data:/i.test(x))throw Error('A field contains an oversized value or embedded file. Remove it before syncing.');return x;}
function syncId(x){return typeof x==='string'&&/^[A-Za-z0-9_.:-]{1,160}$/.test(x)&&!['__proto__','constructor','prototype'].includes(x);}
function syncRows(value,fields){if(!Array.isArray(value)||value.length>3000)throw Error('Invalid or oversized list.');return value.map(x=>{if(!x||typeof x!=='object'||Array.isArray(x))throw Error('Invalid list entry.');const row={};for(const k of fields){const v=x[k];if(k==='done')row[k]=v===true;else if(k==='amount'){if(typeof v!=='number'||!Number.isFinite(v)||v<0)throw Error('Invalid expense amount.');row[k]=v;}else if(k==='wait'){if(v==null)row[k]=null;else if(typeof v==='number'&&Number.isFinite(v)&&v>=0)row[k]=v;else throw Error('Invalid ride wait.');}else {if(v!=null&&typeof v!=='string')throw Error('Invalid planning text.');row[k]=syncText(v);}}return row;});}
function syncParkList(x){if(!Array.isArray(x)||x.length>2000||x.some(v=>!syncId(v)))throw Error('Invalid park or attraction list.');return [...new Set(x)];}
function syncDays(value){const out={};for(const [date,d] of Object.entries(syncObject(value))){if(!/^\d{4}-\d{2}-\d{2}$/.test(date))continue;const source=Array.isArray(d)?{parks:d}:syncObject(d);const item={};if(Object.hasOwn(source,'parks'))item.parks=syncParkList(source.parks);out[date]=item;}return out;}
function syncDayLabels(value){const out={};for(const [date,label] of Object.entries(syncObject(value)))if(/^\d{4}-\d{2}-\d{2}$/.test(date)&&typeof label==='string')out[date]=syncText(label);return out;}
function syncFavorites(value){const out={};for(const [k,v] of Object.entries(syncObject(value)))if(syncId(k))out[k]=syncParkList(v);return out;}
function syncParks(value,keys){const out={};for(const k of keys){if(!syncId(k))continue;const p=syncObject(value[k]);const row={};for(const field of ['name','destName'])if(typeof p[field]==='string')row[field]=syncText(p[field]);if(row.name)out[k]=row;}return out;}
function validateSnapshot(kind,x){if(x?.schema!==1)throw Error('Unsupported cloud snapshot version.');let out={schema:1};if(kind==='profile'){out.favorites=syncFavorites(x.favorites);out.parks=syncParks(syncObject(x.parks),Object.keys(out.favorites));out.theme=['auto','day','night'].includes(x.theme)?x.theme:'auto';out.galleryPrefs={theme:['auto','day','night'].includes(x.galleryPrefs?.theme)?x.galleryPrefs.theme:'auto',rotation:x.galleryPrefs?.rotation!==false};}else{out.time=/^(?:[01]\d|2[0-3]):[0-5]\d$/.test(x.time||'')?x.time:'15:00';out.days=syncDays(x.days);out.details={};const d=syncObject(x.details);for(const [k,fields] of Object.entries(syncFields)){const fallback=k==='checks'?syncDefaults.map(name=>({name,done:false})):[];out.details[k]=syncRows(d[k]??fallback,fields);}out.details.budget=typeof d.budget==='number'&&Number.isFinite(d.budget)&&d.budget>=0?d.budget:0;out.details.mode=['auto','Countdown','Travel','Vacation','Memories'].includes(d.mode)?d.mode:'auto';out.details.dayParks=syncDayLabels(d.dayParks);out.parks=syncParks(syncObject(x.parks),Object.values(out.days).flatMap(d=>d.parks||[]));}if(new TextEncoder().encode(JSON.stringify(out)).length>900000)throw Error('Snapshot is too large.');return out;}
function snapshotTrip(t){const local=linkedLocal(t),link=local&&localLink(local.id);if(!local||link?.owner!==user.id||link.cloud!==t.id)throw Error('Restore or link this countdown first.');return {local,payload:validateSnapshot('trip',{schema:1,time:local.time,days:local.days,details:readObject(COMPANION_KEY).data?.[local.id],parks:state.parks||{}})};}
function snapshotProfile(){const v=readObject(COMPANION_KEY);return validateSnapshot('profile',{schema:1,favorites:{...syncObject(v.favorites),...syncObject(state.favs)},parks:state.parks||{},theme:v.theme,galleryPrefs:v.galleryPrefs});}
function mergeParkMetadata(incoming){state.parks=state.parks||{};for(const [k,v] of Object.entries(incoming))state.parks[k]={...syncObject(state.parks[k]),...v};}
function applyTripSnapshot(t,payload){const p=validateSnapshot('trip',payload),{local}=snapshotTrip(t);const v=readObject(COMPANION_KEY);v.data=syncObject(v.data);v.data[local.id]={...syncObject(v.data[local.id]),...p.details};const days=syncObject(local.days);const next={};for(const date of new Set([...Object.keys(days),...Object.keys(p.days)])){const old=Array.isArray(days[date])?{parks:days[date]}:syncObject(days[date]);const d={...old};delete d.parks;if(Object.hasOwn(p.days,date))Object.assign(d,p.days[date]);if(Object.keys(d).length)next[date]=d;}localStorage.setItem(COMPANION_KEY,JSON.stringify(v));local.days=next;local.time=p.time;mergeParkMetadata(p.parks);save();}
function applyProfileSnapshot(payload){const p=validateSnapshot('profile',payload),v=readObject(COMPANION_KEY);v.favorites=p.favorites;v.theme=p.theme;v.galleryPrefs=p.galleryPrefs;localStorage.setItem(COMPANION_KEY,JSON.stringify(v));state.favs=p.favorites;mergeParkMetadata(p.parks);save();}
function syncScope(t){return t?'trip:'+t.id:'profile';}
function syncMeta(){return readObject(SYNC_KEY);}
function syncAccountGuard(t){if(!user?.id)throw Error('Sign in first.');requireDeviceAccess(false);if(!t){const owner=syncMeta().profileOwner;if(owner&&owner!==user.id)throw Error('This browser’s shared favorites were linked to another account. Use a separate browser profile.');}else snapshotTrip(t);return user.id;}
function syncSeen(scope,owner){return syncMeta().seen?.[owner]?.[scope];}
function recordSync(scope,owner,revision){if(user?.id!==owner)throw Error('Account changed. Sign in again.');requireDeviceAccess(true);const m=syncMeta();m.seen=syncObject(m.seen);m.seen[owner]=syncObject(m.seen[owner]);m.seen[owner][scope]=revision;if(scope==='profile')m.profileOwner=owner;localStorage.setItem(SYNC_KEY,JSON.stringify(m));}
function syncRevision(row){if(!Number.isSafeInteger(row?.revision)||row.revision<1)throw Error('Invalid cloud snapshot revision.');return row.revision;}
async function getSnapshot(t){const owner=user?.id;if(!owner)throw Error('Sign in first.');const scope=syncScope(t),r=unwrap(await api.from('account_sync_snapshots').select('scope,revision,payload,updated_at').eq('owner_id',owner).eq('scope',scope).maybeSingle());if(user?.id!==owner)throw Error('Account changed.');return r;}
async function publishSnapshot(t,remote){const owner=syncAccountGuard(t),scope=syncScope(t);if(remote&&syncSeen(scope,owner)!==syncRevision(remote))throw Error('Cloud plans changed or have not been restored on this device. Restore the latest snapshot before publishing.');if(!remote&&syncSeen(scope,owner)!==undefined)throw Error('The cloud snapshot is missing. Refresh before publishing.');if(!confirm('Publish the listed planning data from this trusted device to your private account? Confirm these are your own plans. Photos and walking history are excluded.'))return;const payload=t?snapshotTrip(t).payload:snapshotProfile();let saved;if(remote){saved=unwrap(await api.from('account_sync_snapshots').update({payload}).eq('owner_id',owner).eq('scope',scope).eq('revision',syncRevision(remote)).select('revision').maybeSingle());if(!saved)throw Error('Cloud plans changed on another device. Reload Cloud sync.');}else{const r=await api.from('account_sync_snapshots').insert({scope,trip_id:t?.id||null,payload}).select('revision').single();if(r.error?.code==='23505')throw Error('Another device created a snapshot. Reload Cloud sync.');saved=unwrap(r);}recordSync(scope,owner,syncRevision(saved));message('Planning data saved to your account.');await loadCloudSync();}
async function restoreSnapshot(t,remote){const owner=syncAccountGuard(t),scope=syncScope(t);if(!remote)throw Error('No cloud snapshot available.');if(!confirm('Replace the supported local planning fields with this cloud snapshot? Unsaved local changes to these fields will be replaced. Close other app tabs first. Photos, walking history and unrelated trips stay on this device. The app will reload.'))return;const current=await getSnapshot(t);if(!current||syncRevision(current)!==syncRevision(remote))throw Error('Cloud plans changed. Reload Cloud sync and review again.');syncAccountGuard(t);if(user?.id!==owner)throw Error('Account changed.');if(t)applyTripSnapshot(t,current.payload);else applyProfileSnapshot(current.payload);recordSync(scope,owner,current.revision);storage('parkCountdown.portal.syncReturn','1');location.reload();}
function cloudSyncScreen(){if(!user){openPortal('auth');return;}const c=card('Cloud planning sync','Save or restore private planning data explicitly. Sync is separate from planner publications and from trip dates/reservations. Use a trusted browser; close other app tabs before restoring.');row(c,button('Back to my account',()=>openPortal('dashboard')),button('Refresh snapshots',()=>loadCloudSync()));const list=card('Your planning snapshots','Loading…');list.id='pc-sync-list';loadCloudSync().catch(e=>message(e.message));}
function syncSummary(t,p){return t?`${Object.keys(p.days).length} park days · ${p.details.plans.length} activities · ${p.details.checks.length} packing items · ${p.details.expenses.length} expenses · ${p.details.rides.length} rides · ${p.details.milestones.length} milestones`:`${Object.values(p.favorites).reduce((a,b)=>a+b.length,0)} favorite attractions · gallery preferences`;}
let cloudSyncRequest=0;
async function loadCloudSync(){const request=++cloudSyncRequest,owner=user?.id;if(!owner)return;const trips=unwrap(await api.from('account_trips').select('id,title,arrival,departure').order('arrival'));const snapshots=unwrap(await api.from('account_sync_snapshots').select('scope,revision,payload,updated_at').eq('owner_id',owner));if(request!==cloudSyncRequest||user?.id!==owner||view!=='cloudsync'||root.hidden)return;const list=root.querySelector('#pc-sync-list');if(!list)return;list.replaceChildren(el('h2','Your planning snapshots'));for(const t of [null,...trips]){const scope=syncScope(t),remote=snapshots.find(x=>x.scope===scope),c=el('article','','pc-card');c.append(el('h3',t?t.title:'Favorites & preferences'));if(t)c.append(el('p',t.arrival+' → '+t.departure,'pc-sub'));let valid=true;try{syncAccountGuard(t);const p=t?snapshotTrip(t).payload:snapshotProfile();c.append(el('p','On this device: '+syncSummary(t,p)));}catch(e){valid=false;c.append(el('p',e.message));}if(remote){try{const p=validateSnapshot(t?'trip':'profile',remote.payload);c.append(el('p','In cloud: '+syncSummary(t,p)),el('p','Version '+syncRevision(remote)+' · '+String(remote.updated_at||'').slice(0,10),'pc-sub'));}catch(e){valid=false;c.append(el('p',e.message));}}else c.append(el('p','No cloud snapshot yet.','pc-sub'));if(valid){const canPublish=remote?syncSeen(scope,owner)===remote.revision:syncSeen(scope,owner)===undefined;const pub=button('Publish device plans',()=>publishSnapshot(t,remote),true);pub.disabled=!canPublish;const restore=button('Restore cloud plans',()=>restoreSnapshot(t,remote));restore.disabled=!remote;row(c,pub,restore);if(!canPublish)c.append(el('p','Restore the current cloud version before publishing.','pc-sub'));}list.append(c);}}

// Phase 7: account-scoped in-app inbox. No browser notification permissions or external delivery.
const notificationDefaults=Object.freeze({payments:true,reservations:true,preparation:true,lead_days:7});
function notificationPrefs(x){return {payments:x?.payments!==false,reservations:x?.reservations!==false,preparation:x?.preparation!==false,lead_days:[1,3,7,14].includes(x?.lead_days)?x.lead_days:7};}
function noticeDate(s){if(typeof s!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(s))return null;const d=new Date(s+'T00:00:00Z');return Number.isFinite(d.getTime())&&d.toISOString().slice(0,10)===s?d.getTime()/86400000:null;}
function noticeToday(d=new Date()){return `${String(d.getFullYear()).padStart(4,'0')}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function noticeId(s){return typeof s==='string'&&/^[A-Za-z0-9_.-]{1,160}$/.test(s);}
function buildNotifications(trips,updates,announcements,snapshots,prefs,today){
 const out=new Map(), day=noticeDate(today);if(day===null)throw Error('Invalid reminder date.');const p=notificationPrefs(prefs), tripMap=new Map(trips.map(t=>[t.id,t]));
 const add=(key,type,title,body,trip,date,priority=2)=>{if(key.length<=300&&!out.has(key))out.set(key,{key,type,title,body,trip,date,priority});};
 const delta=s=>{const n=noticeDate(s);return n===null?null:n-day;};const upcoming=s=>{const n=delta(s);return n!==null&&n>=0&&n<=p.lead_days;};
 for(const t of trips){if(!noticeId(t.id))continue;const trip=t.id, name=t.title||'Vacation';
  if(p.preparation&&t.status==='booked'&&upcoming(t.arrival))add(`arrival:${trip}:${t.arrival}`,'Preparation',name+' is approaching',`Arrival ${t.arrival}. Review your travel plans and packing list.`,trip,t.arrival);
  if(t.status==='research')continue;
  for(const r of reservationRows(t)){if(!noticeId(r.id)||!['Planned','Confirmed','Completed'].includes(r.status))continue;
   const balance=r.cost_cents-r.paid_cents, due=delta(r.due_date), title=String(r.title||'Reservation');
   if(p.payments&&Number.isSafeInteger(balance)&&balance>0&&due!==null&&due<=p.lead_days)add(`payment:${trip}:${r.id}:${r.due_date}:${balance}:${due<0?'late':'due'}`,'Payment',`${due<0?'Overdue payment':due===0?'Payment due today':'Upcoming payment'} · ${title}`,`${name} · ${usd(balance)} remaining · due ${r.due_date}`,trip,r.due_date,due<0?0:1);
   if(p.reservations&&r.status!=='Completed'&&r.kind!=='Payment / invoice'&&upcoming(r.date))add(`booking:${trip}:${r.id}:${r.date}:${String(r.time||'').replace(/[^0-9:]/g,'').slice(0,5)}`,'Reservation',`${r.kind||'Booking'} · ${title}`,`${name} · ${r.date}${r.time?' at '+String(r.time).slice(0,5)+' (activity local time)':''}`,trip,r.date,delta(r.date)===0?1:2);
  }
 }
 if(p.preparation)for(const s of snapshots){if(!tripMap.has(s.trip_id)||!noticeId(s.trip_id)||s.scope!=='trip:'+s.trip_id||s.payload?.schema!==1)continue;const list=s.payload?.details?.milestones;if(!Array.isArray(list))continue;for(const m of list.slice(0,3000)){if(!noticeId(m?.id)||m.done===true||!upcoming(m.date)||typeof m.name!=='string')continue;add(`prep:${s.trip_id}:${m.id}:${m.date}`,'Preparation',m.name.slice(0,160),`${tripMap.get(s.trip_id).title} · target ${m.date} · from your published cloud plan`,s.trip_id,m.date);}}
 for(const u of updates){if(!tripMap.has(u.trip_id)||!noticeId(u.trip_id)||!Number.isSafeInteger(u.published_revision)||u.published_revision<=u.applied_revision)continue;add(`update:${u.trip_id}:${u.published_revision}`,'Planner update','Your planner updated '+tripMap.get(u.trip_id).title,'Review and apply published changes to your cloud trip.',u.trip_id,String(u.published_at||''),1);}
 for(const a of announcements){if(!tripMap.has(a.trip_id)||!noticeId(a.id))continue;add('message:'+a.id,'Planner message',String(a.subject||'Message from planner').slice(0,120),String(a.body||'').slice(0,2000),a.trip_id,String(a.created_at||''),1);}
 return [...out.values()].sort((a,b)=>a.priority-b.priority||(a.type==='Planner message'&&b.type==='Planner message'?b.date.localeCompare(a.date):a.date.localeCompare(b.date))||a.key.localeCompare(b.key));
}
let notificationSequence=0, notificationChecking=false, notificationFilter='all';
async function notificationData(owner){
 const [trips,prefs,updates,msgs,snaps]=await Promise.all([
  api.from('account_trips').select('id,title,arrival,status,reservations').order('arrival'),
  api.from('account_notification_preferences').select('payments,reservations,preparation,lead_days').eq('owner_id',owner).maybeSingle(),
  api.rpc('my_collaboration_updates'),
  api.from('account_planner_announcements').select('id,trip_id,subject,body,created_at').eq('owner_id',owner).order('created_at',{ascending:false}).limit(100),
  api.from('account_sync_snapshots').select('scope,trip_id,payload').eq('owner_id',owner).not('trip_id','is',null)
 ]);
 if(user?.id!==owner)throw Error('Account changed.');
 const preferences=notificationPrefs(unwrap(prefs)), rows=buildNotifications(unwrap(trips)||[],unwrap(updates)||[],unwrap(msgs)||[],unwrap(snaps)||[],preferences,noticeToday());
 // Limit the active list and use exact-key batched reads to avoid large URL/result limits.
 const visible=rows.slice(0,200), read=new Set();for(let i=0;i<visible.length;i+=25){const batch=visible.slice(i,i+25).map(x=>x.key);const result=unwrap(await api.from('account_notification_reads').select('notice_key').eq('owner_id',owner).in('notice_key',batch));for(const x of result||[])read.add(x.notice_key);}
 return {preferences,rows:visible.map(n=>({...n,read:read.has(n.key)})),truncated:rows.length>visible.length};
}
function notificationsScreen(){if(!user){openPortal('auth');return;}const head=card('Notification center','In-app reminders and private planner announcements. Dates use this device’s calendar day; this is not an alarm or email delivery service.');row(head,button('Back to my trips',()=>openPortal('dashboard')),button('Refresh notifications',()=>refreshNotifications(true)));const panel=card('Inbox','Loading…');panel.id='pc-notification-list';const settings=card('Reminder preferences','Choose which planning reminders appear. Planner messages and published updates are always shown.');settings.id='pc-notification-settings';refreshNotifications(true);}
function drawNotificationPreferences(panel,p){if(!panel||panel.dataset.ready)return;panel.dataset.ready='1';const [f,b]=formCard(panel,async data=>{const owner=user?.id;unwrap(await api.rpc('save_notification_preferences',{p_payments:data.has('payments'),p_reservations:data.has('reservations'),p_preparation:data.has('preparation'),p_lead_days:Number(data.get('lead_days'))}));if(user?.id===owner){message('Reminder preferences saved.');await refreshNotifications(true);}},'Save reminder preferences');for(const [key,label] of [['payments','Payment deadlines'],['reservations','Upcoming bookings'],['preparation','Trip arrival and preparation milestones']]){const l=el('label','','pc-notice-check');const input=el('input');input.type='checkbox';input.name=key;input.checked=p[key];l.append(input,el('span',label));f.append(l);}field(f,'Reminder window (days)','lead_days',p.lead_days,'select',{options:['1','3','7','14']});f.append(b);}
async function refreshNotifications(force=false){
 if(!api||!user||root.hidden||document.hidden||!['notifications','dashboard'].includes(view)||notificationChecking&&!force)return;
 const owner=user.id, active=view, panel=root.querySelector(active==='notifications'?'#pc-notification-list':'#pc-notification-summary');if(!panel)return;
 const seq=++notificationSequence;notificationChecking=true;try{const data=await notificationData(owner);if(seq!==notificationSequence||user?.id!==owner||view!==active||!panel.isConnected)return;
 const unread=data.rows.filter(n=>!n.read).length;if(active==='dashboard'){panel.textContent=`${unread} unread in-app notification${unread===1?'':'s'}${data.truncated?' (first 200 shown)':''}`;return;}
 panel.replaceChildren(el('h2','Inbox'),el('p',`${unread} unread · ${data.rows.length} shown${data.truncated?' · additional reminders not shown':''}. Latest 100 planner messages are considered.`,'pc-sub'));
 const filter=el('select');filter.setAttribute('aria-label','Filter notifications');for(const [value,label] of [['all','All notifications'],['unread','Unread only'],['Payment','Payments'],['Reservation','Reservations'],['Preparation','Preparation'],['Planner message','Planner messages'],['Planner update','Planner updates']]){const o=el('option',label);o.value=value;filter.append(o);}filter.value=notificationFilter;panel.append(filter);const list=el('div');panel.append(list);
 const draw=()=>{list.replaceChildren();for(const n of data.rows.filter(x=>notificationFilter==='all'||(notificationFilter==='unread'?!x.read:x.type===notificationFilter))){const item=el('article','','pc-res-item pc-notice-item');item.append(el('p',`${n.type} · ${n.read?'Read':'Unread'}`,'pc-sub'),el('h3',n.title),el('p',n.body,'pc-res-notes'));if(n.type==='Planner message')item.append(el('p',n.date.slice(0,10),'pc-sub'));const actions=row(item);if(!n.read)actions.append(button('Mark read',async()=>{if(user?.id!==owner)return;unwrap(await api.rpc('mark_notification_read',{p_key:n.key}));if(user?.id===owner){n.read=true;draw();await refreshNotifications(true);}}));if(n.type==='Planner update')actions.append(button('Review planner update',()=>openCollaboration(n.trip),true));else if(['Payment','Reservation'].includes(n.type))actions.append(button('Open reservations',async()=>{const t=unwrap(await api.from('account_trips').select('*').eq('id',n.trip).maybeSingle());if(user?.id===owner&&t)openReservations(t,false);}));list.append(item);}if(!list.children.length)list.append(el('p','No matching notifications.','pc-sub'));};filter.onchange=()=>{notificationFilter=filter.value;draw()};draw();drawNotificationPreferences(root.querySelector('#pc-notification-settings'),data.preferences);
 }catch(e){if(seq===notificationSequence&&user?.id===owner&&panel.isConnected){if(active==='dashboard')panel.textContent='Notifications unavailable · check connection or Phase 7 setup.';else{panel.replaceChildren(el('h2','Inbox'),el('p','Unable to load notifications. '+(e.message||'Check your connection.'),'pc-sub'),button('Retry',()=>refreshNotifications(true)));}}}finally{if(seq===notificationSequence)notificationChecking=false;}
}
function composePlannerAnnouncement(t,c){if(!user||!approved)return;const owner=user.id,scope=plannerWorkspace;c.querySelector('.pc-announcement-form')?.remove();const pane=el('section','','pc-announcement-form pc-card');pane.append(el('h3','Send private announcement'),el('p','Delivered to this connected traveler’s in-app inbox only. Do not include passwords, payment card numbers or other confidential documents.','pc-sub'));const [f,b]=formCard(pane,async d=>{if(!plannerCurrent(owner,scope))throw Error('Planner workspace changed.');const subject=String(d.get('announcement_subject')||'').trim(),body=String(d.get('announcement_body')||'').trim();if(!subject||subject.length>120||!body||body.length>2000)throw Error('Enter a subject and message within the length limits.');if(!confirm('Send this announcement to the connected traveler? Sent messages cannot be edited or recalled.'))return;unwrap(await api.rpc('send_planner_announcement',{p_client:t.id,p_subject:subject,p_body:body}));if(plannerCurrent(owner,scope)){pane.remove();message('Announcement sent to the traveler’s in-app inbox.');}},'Send announcement');field(f,'Subject','announcement_subject','','text',{required:true,maxLength:120});field(f,'Message','announcement_body','','textarea',{required:true,maxLength:2000});f.append(b,button('Cancel',()=>pane.remove()));c.append(pane);}

