function privacyScreen(){if(!user){openPortal('auth');return}const owner=user.id,c=card('Privacy & account','Your personal cloud data and deletion requests. Shared agency records and local picture packs are not part of this export.');c.append(el('p',deviceAllowed()?'This browser may contain local plans and pictures. Sign out on shared devices and use separate browser profiles.':'Local plans are locked for this account. Use a separate browser profile.','pc-sub'));row(c,button('Download my cloud data',async()=>{const data=unwrap(await api.rpc('export_my_account'));if(user?.id!==owner)throw Error('Account changed.');const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=el('a');a.href=url;a.download='park-countdown-personal-data.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);message('Personal export downloaded. Keep it private.');},true));const d=card('Account deletion request','Request administrator review to delete your account. This does not immediately delete records, revoke sessions, remove local copies or erase shared agency data.');const status=el('p','Checking request status…','pc-sub');d.append(status);const request=button('Request account deletion',async()=>{if(user?.id!==owner||!confirm('Request deletion of your account and personal cloud data? An administrator must review it.'))return;unwrap(await api.rpc('request_account_deletion'));if(user?.id===owner){message('Deletion request submitted for administrator review.');render()}},false),cancel=button('Cancel deletion request',async()=>{if(user?.id!==owner)return;unwrap(await api.rpc('cancel_account_deletion'));if(user?.id===owner){message('Deletion request cancelled.');render()}});request.disabled=true;cancel.disabled=true;row(d,request,cancel);(async()=>{try{const r=unwrap(await api.from('account_deletion_requests').select('requested_at').eq('owner_id',owner).maybeSingle());if(user?.id!==owner||!status.isConnected)return;status.textContent=r?'Request pending since '+String(r.requested_at).slice(0,10):'No pending deletion request.';request.disabled=!!r;cancel.disabled=!r;}catch(e){if(status.isConnected)status.textContent='Deletion service unavailable. Check Phase 8 database setup.';}})();}
